<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}

require dirname(__DIR__).'/app/bootstrap.php';
$db->exec("CREATE TABLE IF NOT EXISTS shipments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL UNIQUE,provider VARCHAR(20) NOT NULL,mode VARCHAR(20) NOT NULL,account_fingerprint VARCHAR(64) NOT NULL DEFAULT '',reference VARCHAR(80) NOT NULL UNIQUE,state VARCHAR(24) NOT NULL DEFAULT 'queued',consignment_id VARCHAR(100) NOT NULL DEFAULT '',tracking_code VARCHAR(100) NOT NULL DEFAULT '',provider_status VARCHAR(100) NOT NULL DEFAULT '',carrier_fee DECIMAL(10,2) NULL,cod_amount DECIMAL(10,2) NOT NULL,weight DECIMAL(8,2) NOT NULL DEFAULT 0.5,request_json JSON NOT NULL,error_code VARCHAR(40) NOT NULL DEFAULT '',last_error VARCHAR(700) NOT NULL DEFAULT '',attempts INT NOT NULL DEFAULT 0,last_sync_at DATETIME NULL,provider_updated_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS courier_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,shipment_id BIGINT UNSIGNED NULL,provider VARCHAR(20) NOT NULL,operation VARCHAR(50) NOT NULL,http_status INT NOT NULL DEFAULT 0,outcome VARCHAR(30) NOT NULL,message VARCHAR(700) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS courier_webhooks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(20) NOT NULL,event_hash CHAR(64) UNIQUE NOT NULL,payload JSON NOT NULL,state VARCHAR(20) DEFAULT 'queued',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS courier_actions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,shipment_id BIGINT UNSIGNED NULL,provider VARCHAR(20) NOT NULL,kind VARCHAR(20) NOT NULL,request_key VARCHAR(80) UNIQUE NOT NULL,state VARCHAR(24) DEFAULT 'queued',payload JSON NOT NULL,remote_id VARCHAR(100) DEFAULT '',last_error VARCHAR(700) DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");
foreach(['shipping_region'=>"VARCHAR(20) NOT NULL DEFAULT 'outside'",'delivery_method'=>"VARCHAR(20) NOT NULL DEFAULT 'standard'"]as $k=>$type)if(!query("SHOW COLUMNS FROM orders LIKE '$k'")->fetch())$db->exec("ALTER TABLE orders ADD COLUMN `$k` $type");
echo "Courier schema ready.\n";
